for (const id in HIMG) HART[id] = () => `<rect width="100" height="100" fill="#1a120c"/><image href="${HIMG[id]}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice" style="image-rendering:auto"/>`;
// portrait du héros : version éveillée si elle existe
const heroArt = (h, aw) => 'art-h-' + h + (aw && HART[h + '_aw'] ? '_aw' : '');
// invocations (animaux de pacte) : images fournies par l'utilisateur
const TIMG = {
  tk_toad:'data:image/jpeg;base64,',
  tk_slug:'data:image/jpeg;base64,',
  tk_snake:'data:image/jpeg;base64,',
  tk_shark:'data:image/jpeg;base64,',
};
for (const id in TIMG) ART[id] = () => `<image href="${TIMG[id]}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice"/>`;

// fond de l'étendard Ninja (choix de l'univers) : image fournie par l'utilisateur
const BAN_NJ = 'data:image/jpeg;base64,';
(function () { const st = document.createElement('style'); st.textContent = `.ban.ban-nj{background-image:linear-gradient(180deg,rgba(10,6,3,.12) 0%,rgba(10,6,3,.45) 34%,rgba(10,6,3,.82) 66%),url(${BAN_NJ});background-size:cover;background-position:center 30%}`; document.head.appendChild(st); })();

// portraits des héros Dragon Ball fournis par l'utilisateur (classique + éveil)
const DBIMG = {
  dh_goku:'data:image/jpeg;base64,',
  dh_goku_aw:'data:image/jpeg;base64,',
  dh_vegeta:'data:image/jpeg;base64,',
  dh_vegeta_aw:'data:image/jpeg;base64,',
  dh_gohan:'data:image/jpeg;base64,',
  dh_gohan_aw:'data:image/jpeg;base64,',
  dh_trunks:'data:image/jpeg;base64,',
  dh_trunks_aw:'data:image/jpeg;base64,',
  dh_goten:'data:image/jpeg;base64,',
  dh_goten_aw:'data:image/jpeg;base64,',
};
for (const id in DBIMG) HART[id] = () => `<rect width="100" height="100" fill="#fff"/><image href="${DBIMG[id]}" x="0" y="0" width="100" height="100" preserveAspectRatio="xMidYMid slice"/>`;

// portraits Dragon Ball (2e planche)
